:root {
  --bg1: #0c1120;
  --bg2: #192540;
  --hud: rgba(8, 12, 22, 0.65);
  --panel: rgba(13, 18, 32, 0.9);
  --text: #edf6ff;
  --accent: #69d2ff;
  --accent-2: #9bff9a;
  --warning: #ffb347;
  --danger: #ff6464;
  --shadow: rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  font-family: Arial, Helvetica, sans-serif;
  background: linear-gradient(180deg, var(--bg1), var(--bg2));
  color: var(--text);
}

body {
  display: grid;
  place-items: center;
  overflow: hidden;
}

.game-shell {
  position: relative;
  width: min(96vw, 960px);
  height: min(92vh, 540px);
  border: 2px solid rgba(255, 255, 255, 0.18);
  border-radius: 16px;
  overflow: hidden;
  background: linear-gradient(180deg, #101b33, #1e385d 35%, #6ca7d9 100%);
  box-shadow: 0 24px 70px var(--shadow);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, #78b4ef 0%, #d8efff 26%, #7dc9d4 52%, #6b8e44 100%);
}

#hud {
  position: absolute;
  inset: 0 0 auto 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 16px 18px;
  color: var(--text);
  pointer-events: none;
  background: linear-gradient(180deg, rgba(5, 10, 18, 0.6), transparent 80%);
}

.hud-left, .hud-right {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--hud);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  padding: 10px 12px;
  backdrop-filter: blur(3px);
}

.title {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

#status {
  color: var(--accent);
  font-size: 0.8rem;
  letter-spacing: 0.04em;
}

.hud-right {
  align-items: flex-end;
  min-width: 170px;
  font-size: 0.9rem;
}

#overlay {
  position: absolute;
  inset: 0;
  display: none;
  place-items: center;
  background: rgba(7, 10, 17, 0.45);
}

#overlay.visible {
  display: grid;
}

.panel {
  width: min(80%, 440px);
  background: var(--panel);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 18px;
  padding: 28px 24px 20px;
  box-shadow: 0 22px 60px rgba(0,0,0,0.45);
  text-align: center;
}

.panel h1 {
  margin: 0 0 14px;
  font-size: clamp(1.8rem, 4vw, 3rem);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.panel p {
  margin: 0 0 10px;
  font-size: 1rem;
  line-height: 1.4;
}

.panel .small {
  opacity: 0.8;
  font-size: 0.9rem;
}

button {
  margin-top: 12px;
  border: none;
  border-radius: 999px;
  padding: 12px 22px;
  font-size: 1rem;
  font-weight: 700;
  color: #0d1b2c;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 10px 26px rgba(105, 210, 255, 0.38);
}

button:hover {
  transform: translateY(-1px);
}

button:active {
  transform: translateY(1px);
}

@media (max-width: 640px) {
  .game-shell {
    width: 100vw;
    height: 100vh;
    border-radius: 0;
  }

  #hud {
    padding: 12px 10px;
    gap: 8px;
  }

  .title {
    font-size: 0.9rem;
  }

  .hud-left, .hud-right {
    padding: 8px 10px;
  }

  .hud-right {
    min-width: 120px;
    font-size: 0.75rem;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const hud = {
  status: document.getElementById('status'),
  distance: document.getElementById('distanceValue'),
  speed: document.getElementById('speedValue'),
  health: document.getElementById('healthValue'),
};

const overlay = document.getElementById('overlay');
const startButton = document.getElementById('startButton');

const WORLD_WIDTH = 2000;
const BASE_GRAVITY = 0.48;
const MAX_SPEED = 18;
const HILL_TOP = 110;

const keys = {
  left: false,
  right: false,
  jump: false,
};

const state = {
  started: false,
  ended: false,
  time: 0,
  distance: 0,
  score: 0,
  health: 3,
  speed: 0,
  cameraX: 0,
  drag: 0,
  lastTimestamp: 0,
};

const rider = {
  x: 170,
  y: 240,
  width: 26,
  height: 36,
  vx: 0,
  vy: 0,
  grounded: false,
  facing: 1,
};

const pickups = [];
const particles = [];

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function rand(min, max) {
  return Math.random() * (max - min) + min;
}

function createPickup(x, y, type = 'boost') {
  pickups.push({
    x,
    y,
    radius: 12,
    type,
    bob: rand(0, Math.PI * 2),
    pulse: rand(0, 1),
  });
}

function generateTrack() {
  pickups.length = 0;
  for (let i = 0; i < 26; i += 1) {
    const x = 80 + i * 92 + rand(-10, 10);
    const hillOffset = Math.sin(i * 1.3) * 40;
    const y = 338 - hillOffset + rand(-24, 24);
    createPickup(x, y, i % 5 === 0 ? 'boost' : 'coin');
  }
}

function resetGame() {
  state.started = false;
  state.ended = false;
  state.time = 0;
  state.distance = 0;
  state.score = 0;
  state.health = 3;
  state.speed = 0;
  state.cameraX = 0;
  state.drag = 0;
  rider.x = 170;
  rider.y = 240;
  rider.vx = 0;
  rider.vy = 0;
  rider.grounded = false;
  rider.facing = 1;
  particles.length = 0;
  generateTrack();
  updateHud();
}

function updateHud() {
  hud.distance.textContent = `${Math.floor(state.distance)} m`;
  hud.speed.textContent = `${Math.round(state.speed * 18)} km/h`;
  hud.health.textContent = `${state.health}`;
  hud.status.textContent = state.ended
    ? (state.distance >= 2600 ? 'You survived the slope!' : 'Run ended')
    : state.started
      ? 'Descending'
      : 'Ready for the drop';
}

function startGame() {
  resetGame();
  state.started = true;
  overlay.classList.remove('visible');
  updateHud();
}

function endGame(message) {
  state.ended = true;
  state.started = false;
  hud.status.textContent = message || 'Run ended';
  overlay.classList.add('visible');
  overlay.querySelector('.panel').innerHTML = `
    <h1>${state.distance >= 2600 ? 'Trail Cleared' : 'Run Over'}</h1>
    <p>${state.distance >= 2600 ? 'You conquered the descent and reached the finish.' : 'The mountain won this run.'}</p>
    <p class="small">Distance: ${Math.floor(state.distance)} m • Speed: ${Math.round(state.speed * 18)} km/h</p>
    <button id="startButton" type="button">${state.distance >= 2600 ? 'Ride Again' : 'Retry Run'}</button>
  `;
  document.getElementById('startButton').addEventListener('click', () => {
    startGame();
  });
}

function createParticles(x, y, color, count) {
  for (let i = 0; i < count; i += 1) {
    particles.push({
      x,
      y,
      vx: rand(-1.6, 1.6),
      vy: rand(-2.2, 0.4),
      life: rand(14, 28),
      size: rand(2, 5),
      color,
    });
  }
}

function handleInput() {
  if (!state.started || state.ended) return;

  const move = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
  if (move !== 0) {
    rider.vx += move * 0.38;
    rider.facing = move;
  }

  if (keys.jump && rider.grounded) {
    rider.vy = -8.5;
    rider.grounded = false;
    createParticles(rider.x, rider.y + rider.height, '#b7edff', 7);
  }
}

function updateRider() {
  const slopeBase = 330 + Math.sin((rider.x + state.cameraX) * 0.008) * 52;
  const groundY = Math.max(290, slopeBase);

  state.speed = clamp(state.speed + (keys.right || keys.left ? 0.08 : 0.03), 0, MAX_SPEED);
  rider.vx *= 0.94;
  rider.vx = clamp(rider.vx, -5.4, 5.4);
  rider.vy += BASE_GRAVITY;
  rider.x += rider.vx + state.speed * 0.4;
  rider.y += rider.vy;

  if (rider.y + rider.height >= groundY) {
    rider.y = groundY - rider.height;
    rider.vy = 0;
    rider.grounded = true;
  } else {
    rider.grounded = false;
  }

  rider.x = clamp(rider.x, 40, WORLD_WIDTH - 60);
  state.cameraX = clamp(rider.x - canvas.width * 0.4, 0, WORLD_WIDTH - canvas.width);
  state.distance = Math.max(state.distance, rider.x);
  state.drag = (state.speed * 0.3) + 0.45;

  if (rider.x > 2450 || rider.y > canvas.height + 160) {
    endGame('Run ended');
  }
}

function checkPickups() {
  for (let i = pickups.length - 1; i >= 0; i -= 1) {
    const pickup = pickups[i];
    const dx = Math.abs(pickup.x - rider.x);
    const dy = Math.abs(pickup.y - rider.y);

    if (dx < 28 && dy < 26) {
      pickups.splice(i, 1);
      if (pickup.type === 'boost') {
        state.speed = clamp(state.speed + 2.2, 0, MAX_SPEED + 2);
        createParticles(pickup.x, pickup.y, '#74f0a8', 18);
      } else {
        state.score += 25;
        createParticles(pickup.x, pickup.y, '#ffe08a', 12);
      }
    }
  }
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i -= 1) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.life -= 1;
    p.vy += 0.08;
    if (p.life <= 0) {
      particles.splice(i, 1);
    }
  }
}

function updateGame() {
  if (!state.started || state.ended) return;

  state.time += 1;
  handleInput();
  updateRider();
  checkPickups();
  updateParticles();

  if (state.distance >= 2600) {
    endGame('Trail Cleared');
  }

  if (state.time % 120 === 0 && state.speed > 10) {
    state.health -= 1;
    createParticles(rider.x, rider.y + 18, '#ff7b72', 11);
    if (state.health <= 0) {
      endGame('You were wrecked');
    }
  }

  updateHud();
}

function drawBackground() {
  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#8ec6ff');
  sky.addColorStop(0.4, '#d7f0ff');
  sky.addColorStop(0.67, '#b8d7a6');
  sky.addColorStop(1, '#6a8d43');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let i = 0; i < 25; i += 1) {
    const x = (i * 120 - state.cameraX * 0.25) % (canvas.width + 100);
    const y = 40 + (i % 5) * 18;
    ctx.fillStyle = 'rgba(255,255,255,0.7)';
    ctx.fillRect(x, y, 42, 10);
  }

  ctx.fillStyle = '#3a6a35';
  for (let i = 0; i < canvas.width + 100; i += 50) {
    const hillX = i - (state.cameraX * 0.7 % 50);
    ctx.beginPath();
    ctx.moveTo(hillX, canvas.height);
    ctx.quadraticCurveTo(hillX + 24, 100, hillX + 50, canvas.height);
    ctx.fill();
  }
}

function drawTrack() {
  const trackY = canvas.height - 30;
  const startX = -state.cameraX;

  ctx.beginPath();
  ctx.moveTo(startX, trackY);
  for (let x = 0; x <= canvas.width + 100; x += 18) {
    const worldX = x + state.cameraX;
    const y = 330 + Math.sin(worldX * 0.02) * 32 + Math.cos(worldX * 0.015) * 18;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(canvas.width + 100, canvas.height);
  ctx.lineTo(-20, canvas.height);
  ctx.closePath();
  ctx.fillStyle = '#4f4d52';
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(startX, trackY);
  for (let x = 0; x <= canvas.width + 100; x += 18) {
    const worldX = x + state.cameraX;
    const y = 330 + Math.sin(worldX * 0.02) * 32 + Math.cos(worldX * 0.015) * 18;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(canvas.width + 100, canvas.height);
  ctx.strokeStyle = '#a5a0a7';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.fillStyle = '#7b6f47';
  for (let i = 0; i < 36; i += 1) {
    const x = (i * 26) - (state.cameraX * 2.1) % 26;
    const y = 335 + Math.sin((i + state.cameraX * 0.1) * 0.8) * 8;
    ctx.fillRect(x, y, 10, 12);
  }
}

function drawPickups() {
  const cameraOffsetX = -state.cameraX;
  for (const pickup of pickups) {
    const screenX = pickup.x + cameraOffsetX;
    const screenY = pickup.y + Math.sin(state.time * 0.1 + pickup.bob) * 2.4;

    ctx.beginPath();
    ctx.arc(screenX, screenY, pickup.radius, 0, Math.PI * 2);
    ctx.fillStyle = pickup.type === 'boost' ? '#7dffb2' : '#f5d777';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(screenX, screenY, pickup.radius * 0.5, 0, Math.PI * 2);
    ctx.fillStyle = pickup.type === 'boost' ? '#d2ffe7' : '#fff2b9';
    ctx.fill();
  }
}

function drawRider() {
  const px = rider.x - state.cameraX;
  const py = rider.y;

  ctx.save();
  ctx.translate(px, py);
  ctx.scale(rider.facing, 1);

  ctx.fillStyle = '#1a2333';
  ctx.fillRect(-10, 0, 20, 22);
  ctx.fillStyle = '#ffdd99';
  ctx.fillRect(-8, 6, 16, 10);
  ctx.fillStyle = '#1c2f52';
  ctx.fillRect(-10, 22, 7, 14);
  ctx.fillRect(3, 22, 7, 14);

  ctx.fillStyle = '#dbe7ff';
  ctx.fillRect(-4, 1, 8, 5);
  ctx.fillStyle = '#1f1f25';
  ctx.fillRect(-5, 0, 3, 2);
  ctx.fillRect(2, 0, 3, 2);

  ctx.restore();
}

function drawParticles() {
  for (const p of particles) {
    ctx.fillStyle = p.color + 'aa';
    ctx.fillRect(p.x - state.cameraX, p.y, p.size, p.size);
  }
}

function drawHUDText() {
  ctx.fillStyle = 'rgba(10, 20, 30, 0.4)';
  ctx.fillRect(18, canvas.height - 52, 180, 28);
  ctx.fillStyle = '#edf6ff';
  ctx.font = 'bold 16px sans-serif';
  ctx.fillText(`Goal 2600m`, 28, canvas.height - 32);
}

function render() {
  drawBackground();
  drawTrack();
  drawPickups();
  drawParticles();
  drawRider();
  drawHUDText();
}

function loop(timestamp) {
  if (!state.lastTimestamp) state.lastTimestamp = timestamp;
  const delta = Math.min(32, timestamp - state.lastTimestamp);
  state.lastTimestamp = timestamp;
  updateGame();
  render();
  requestAnimationFrame(loop);
}

startButton.addEventListener('click', startGame);
window.addEventListener('keydown', (event) => {
  const key = event.key.toLowerCase();
  if (key === 'a' || key === 'arrowleft') keys.left = true;
  if (key === 'd' || key === 'arrowright') keys.right = true;
  if (key === ' ' || key === 'spacebar') {
    event.preventDefault();
    keys.jump = true;
  }
  if (key === 'enter' && !state.started) startGame();
});

window.addEventListener('keyup', (event) => {
  const key = event.key.toLowerCase();
  if (key === 'a' || key === 'arrowleft') keys.left = false;
  if (key === 'd' || key === 'arrowright') keys.right = false;
  if (key === ' ' || key === 'spacebar') keys.jump = false;
});

resetGame();
render();
requestAnimationFrame(loop);

