function updateRider() {
  const slopeBase = 330 + Math.sin((rider.x + state.cameraX) * 0.008) * 52;
  const groundY = Math.max(290, slopeBase);

  state.speed = clamp(state.speed + (keys.right || keys.left ? 0.08 : 0.03), 0, MAX_SPEED);
  rider.vx *= 0.94;
  rider.vx = clamp(rider.vx, -5.4, 5.4);
  rider.vy += BASE_GRAVITY;
  rider.x += rider.vx + state.speed * 0.45;
  rider.y += rider.vy;

  if (rider.y + rider.height >= groundY) {
    rider.y = groundY - rider.height;
    rider.vy = 0;
    rider.grounded = true;
  } else {
    rider.grounded = false;
