  rider.x = clamp(rider.x, 40, WORLD_WIDTH - 60);
  state.cameraX = clamp(rider.x - canvas.width * 0.4, 0, WORLD_WIDTH - canvas.width);
  state.distance = Math.max(state.distance, rider.x);
  state.drag = (state.speed * 0.3) + 0.45;

